-- =====================================================================
-- 173: Pares de interação para os 24 fármacos sem pares + 5 fármacos
--      novos (parceiros fora da BD) — aumento do catálogo
-- ---------------------------------------------------------------------
-- Objetivo: fechar a lacuna dos 24 fármacos com 0 pares em
-- drug_interactions (auditoria 2026-08-08). Quando o parceiro
-- documentado não existe na BD, o parceiro é adicionado como fármaco
-- novo (padrão da 168: antiácidos, ferro, zinco) — 5 novos:
--   probenecida, colestiramina, tizanidina, amantadina, cetamina.
--
-- Fontes: rótulos aprovados FDA/DailyMed (NIH/NLM) — setIDs validados na
-- API pública v2 (spls.json?drug_name=...) + endpoint XML (spls/{setid}.xml)
-- a 2026-08-17; Prontuário Terapêutico do INFARMED (11.ª ed., 2012) para
-- os sem rótulo FDA ativo (artesunato, butilbrometo de hioscina,
-- etilefrina, fenoximetilpenicilina, nistatina) e para corroborar.
-- Parceiros já existentes: setIDs reutilizados das citações já presentes
-- na BD (regra da secção 15.2).
--
-- Fármacos novos (setIDs validados a 2026-08-17):
--   probenecida   (MARLEX)    5d552de5-2d18-4464-bcaf-0311fa3f080d
--   colestiramina (ASCEND)    430ac07e-8524-4dec-a599-b7ebc56d9563
--   tizanidina    (PREFERRED) 8d0b2b22-e1df-4ad5-92e6-f9a369108e4b
--   amantadina    (GOCOVRI)   2bee0631-0028-1314-e063-6394a90aaaed
--   cetamina      (KETALAR)   14e8f864-8b8a-4e7e-8439-e510d3107063
--
-- Pares (36): todos ancorados nas fontes — ver âncora em cada par.
-- Sem pares (documentados no corpo): aminoácidos, artesunato,
-- butilbrometo de hioscina (ver nota), filgrastim, nistatina,
-- poractanto alfa, primaquina.
--
-- Metodologia (docs/INTERACOES_FLUXO_PESQUISA.md):
--   * pares canónicos (drug_a_id < drug_b_id) via LEAST/GREATEST;
--   * sem pares artificiais: só pares documentados;
--   * idempotente (UNIQUE (drug_a_id, drug_b_id), ON CONFLICT DO NOTHING);
--   * ordem de aplicação: 173 após 171/172 (não depende delas).
-- =====================================================================

-- =====================================================================
-- 1. Fármacos novos (5) — padrão 7.3
-- =====================================================================
INSERT INTO public.drugs (slug, name_pt, name_en, class_pt, class_en, aliases, status, sort_order)
