  ('colestiramina', 'Colestiramina', 'Cholestyramine', 'Sequestrante de ácidos biliares (hipolipemiante)', 'Bile acid sequestrant (lipid-lowering)', ARRAY['Colestiramina', 'Questran'], 'published', 206),
  ('tizanidina', 'Tizanidina', 'Tizanidine', 'Relaxante muscular de ação central (agonista alfa-2 adrenérgico)', 'Centrally acting muscle relaxant (alpha-2 adrenergic agonist)', ARRAY['Tizanidina', 'Sirdalud'], 'published', 207),
  ('amantadina', 'Amantadina', 'Amantadine', 'Antiparkinsónico / antiviral (antagonista NMDA)', 'Antiparkinsonian / antiviral (NMDA antagonist)', ARRAY['Amantadina', 'Symmetrel'], 'published', 208),
  ('cetamina', 'Cetamina', 'Ketamine', 'Anestésico dissociativo (antagonista NMDA)', 'Dissociative anaesthetic (NMDA antagonist)', ARRAY['Cetamina', 'Ketalar'], 'published', 209);

-- =====================================================================
-- 2. Pares (36) — padrão 7.4 (INSERT direto com LEAST/GREATEST)
-- =====================================================================
INSERT INTO public.drug_interactions
  (drug_a_id, drug_b_id, severity, summary_pt, summary_en, mechanism_pt, mechanism_en,
   management_pt, management_en, monitoring_pt, monitoring_en, red_flags_pt, red_flags_en,
   source_pt, source_en, status, updated_at)
VALUES
  -- Acetilcisteína × Nitroglicerina (Prontuário 5.2.2)
  (LEAST((SELECT id FROM public.drugs WHERE slug = 'acetilcisteina'),
        (SELECT id FROM public.drugs WHERE slug = 'nitroglicerina')),
   GREATEST((SELECT id FROM public.drugs WHERE slug = 'acetilcisteina'),
            (SELECT id FROM public.drugs WHERE slug = 'nitroglicerina')),
   'moderate',
   'Acetilcisteína + nitroglicerina: risco de hipotensão e cefaleias quando administradas em conjunto.', 
   'Acetylcysteine + nitroglycerin: risk of hypotension and headache when given together.',
   'O Prontuário Terapêutico regista a interação entre a acetilcisteína e a nitroglicerina (hipotensão e cefaleias) na monografia da acetilcisteína (5.2.2). O mecanismo é a potenciação vasodilatadora — a acetilcisteína aumenta a disponibilidade do óxido nítrico, reforçando o efeito vasodilatador e hipotensor da nitroglicerina.',
   'The Prontuário Terapêutico records the interaction between acetylcysteine and nitroglycerin (hypotension and headache) in the acetylcysteine monograph (5.2.2). The mechanism is vasodilatory potentiation — acetylcysteine increases nitric oxide availability, reinforcing the vasodilatory and hypotensive effect of nitroglycerin.',
   'Monitorizar a tensão arterial durante a co-administração; advertir o doente para o risco de cefaleias e hipotensão ortostática.',
   'Monitor blood pressure during co-administration; warn the patient about the risk of headache and orthostatic hypotension.',
   'Vigilância clínica de sintomas (cefaleias, tonturas, hipotensão) nas primeiras administrações conjuntas.',
   'Clinical monitoring of symptoms (headache, dizziness, hypotension) during the first combined administrations.',
   'Hipotensão sintomática, síncope ou cefaleias intensas após a toma conjunta.',
   'Symptomatic hypotension, syncope or severe headache after combined intake.',
   'Prontuário Terapêutico do INFARMED (11.ª ed., 2012) — Acetilcisteína, 5.2.2',
   'Prontuário Terapêutico do INFARMED (11th ed., 2012) — Acetylcysteine, 5.2.2', 'published', now()),

  -- Ácido ursodesoxicólico × Colestiramina (rótulo FDA 7.1)
  (LEAST((SELECT id FROM public.drugs WHERE slug = 'acido_ursodesoxicolico'),
        (SELECT id FROM public.drugs WHERE slug = 'colestiramina')),
   GREATEST((SELECT id FROM public.drugs WHERE slug = 'acido_ursodesoxicolico'),
            (SELECT id FROM public.drugs WHERE slug = 'colestiramina')),
   'moderate',
   'Ácido ursodesoxicólico + colestiramina: a colestiramina reduz a absorção do ursodesoxicólico — separar as tomas por 4-6 horas.',
   'Ursodeoxycholic acid + cholestyramine: cholestyramine reduces ursodiol absorption — separate doses by 4-6 hours.',
   'O rótulo FDA do ursodiol documenta: "Bile Acid Sequestering Agents: May interfere with the action of ursodiol tablets by reducing its absorption" (7.1). A colestiramina liga-se aos ácidos biliares no lúmen intestinal e reduz a absorção do ursodesoxicólico administrado por via oral, comprometendo o efeito na litíase biliar.',
   'The FDA ursodiol label documents: "Bile Acid Sequestering Agents: May interfere with the action of ursodiol tablets by reducing its absorption" (7.1). Cholestyramine binds bile acids in the gut lumen and reduces the absorption of orally administered ursodiol, compromising its effect in gallstone disease.',
   'Administrar o ácido ursodesoxicólico pelo menos 1 hora antes ou 4-6 horas depois da colestiramina; idealmente espaçar 4-6 horas.',
   'Give ursodeoxycholic acid at least 1 hour before or 4-6 hours after cholestyramine; ideally space by 4-6 hours.',
   'Avaliar a resposta clínica (sintomas biliares, controlo ecográfico quando aplicável) durante a associação.',
   'Assess clinical response (biliary symptoms, ultrasound follow-up when applicable) during the combination.',
   'Falta de resposta ao tratamento da litíase biliar com toma simultânea.',
   'Lack of response in gallstone treatment with simultaneous intake.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Ursodiol (BLUEPOINT LABORATORIES), secção 7.1: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=a3c98080-0a4d-4a93-8dcb-02ab8533050b ; rótulo aprovado Colestiramina (ASCEND LABORATORIES): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=430ac07e-8524-4dec-a599-b7ebc56d9563',
   'DailyMed/FDA (NIH/NLM) — approved Ursodiol label (BLUEPOINT LABORATORIES), section 7.1: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=a3c98080-0a4d-4a93-8dcb-02ab8533050b ; approved Cholestyramine label (ASCEND LABORATORIES): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=430ac07e-8524-4dec-a599-b7ebc56d9563', 'published', now()),

  -- Ácido ursodesoxicólico × Antiácidos (rótulo FDA 7.2 + prontuário)
  (LEAST((SELECT id FROM public.drugs WHERE slug = 'acido_ursodesoxicolico'),
        (SELECT id FROM public.drugs WHERE slug = 'antiacidos')),
   GREATEST((SELECT id FROM public.drugs WHERE slug = 'acido_ursodesoxicolico'),
            (SELECT id FROM public.drugs WHERE slug = 'antiacidos')),
   'moderate',
   'Ácido ursodesoxicólico + antiácidos: os antiácidos com alumínio reduzem a absorção do ursodesoxicólico — separar as tomas.',
   'Ursodeoxycholic acid + antacids: aluminium-containing antacids reduce ursodiol absorption — separate doses.',
   'O rótulo FDA do ursodiol documenta: "Aluminum-based Antacids: May interfere with the action of ursodiol tablets by reducing its absorption" (7.2), e o Prontuário Terapêutico regista a interação com o hidróxido de alumínio na monografia do ácido ursodesoxicólico (6.9.1). A adsorção aos catiões de alumínio reduz a biodisponibilidade oral do ursodesoxicólico.',
   'The FDA ursodiol label documents: "Aluminum-based Antacids: May interfere with the action of ursodiol tablets by reducing its absorption" (7.2), and the Prontuário Terapêutico records the interaction with aluminium hydroxide in the ursodeoxycholic acid monograph (6.9.1). Adsorption to aluminium cations reduces the oral bioavailability of ursodiol.',
   'Separar a toma do ácido ursodesoxicólico dos antiácidos por pelo menos 2 horas.',
   'Separate ursodeoxycholic acid from antacids by at least 2 hours.',
   'Avaliar a resposta clínica durante a associação.',
   'Assess clinical response during the combination.',
   'Falta de resposta ao tratamento com toma simultânea de antiácidos.',
   'Lack of response with simultaneous antacid intake.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Ursodiol (BLUEPOINT LABORATORIES), secção 7.2: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=a3c98080-0a4d-4a93-8dcb-02ab8533050b ; Prontuário Terapêutico do INFARMED (11.ª ed., 2012) — Ácido ursodesoxicólico, 6.9.1',
   'DailyMed/FDA (NIH/NLM) — approved Ursodiol label (BLUEPOINT LABORATORIES), section 7.2: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=a3c98080-0a4d-4a93-8dcb-02ab8533050b ; Prontuário Terapêutico do INFARMED (11th ed., 2012) — Ursodeoxycholic acid, 6.9.1', 'published', now()),

  -- Ipratrópio × Tiotrópio (rótulo FDA 7.1/7.2 — anticolinérgico aditivo)
  (LEAST((SELECT id FROM public.drugs WHERE slug = 'ipratropio'),
        (SELECT id FROM public.drugs WHERE slug = 'tiotropio')),
   GREATEST((SELECT id FROM public.drugs WHERE slug = 'ipratropio'),
            (SELECT id FROM public.drugs WHERE slug = 'tiotropio')),
   'moderate',
   'Ipratrópio + tiotrópio: efeito anticolinérgico aditivo — evitar a associação de anticolinérgicos.',
   'Ipratropium + tiotropium: additive anticholinergic effect — avoid combining anticholinergics.',
   'Os rótulos FDA do ipratrópio (secção 7.1) e do tiotrópio (secção 7.2) documentam: "Anticholinergics: May interact additively with concomitantly used anticholinergic medications. Avoid administration with other anticholinergic-containing drugs". A associação de dois anticolinérgicos inalados aumenta o risco de efeitos sistémicos anticolinérgicos (boca seca, retenção urinária, glaucoma de ângulo fechado, obstipação) sem benefício broncodilatador adicional comprovado.',
   'The FDA labels of ipratropium (section 7.1) and tiotropium (section 7.2) document: "Anticholinergics: May interact additively with concomitantly used anticholinergic medications. Avoid administration with other anticholinergic-containing drugs". Combining two inhaled anticholinergics increases the risk of systemic anticholinergic effects (dry mouth, urinary retention, angle-closure glaucoma, constipation) without proven additional bronchodilator benefit.',
   'Evitar a associação de dois anticolinérgicos inalados (ipratrópio + tiotrópio); optar pela monoterapia com o mais adequado.',
   'Avoid combining two inhaled anticholinergics (ipratropium + tiotropium); choose monotherapy with the most appropriate agent.',
   'Se inevitável, vigiar boca seca, retenção urinária, obstipação e alterações visuais.',
   'If unavoidable, monitor for dry mouth, urinary retention, constipation and visual changes.',
   'Retenção urinária aguda, glaucoma agudo ou taquicardia com a associação.',
   'Acute urinary retention, acute glaucoma or tachycardia with the combination.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Ipratrópio (ARMSTRONG), secção 7.1: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=133cc2ed-f018-4295-b84e-b24382299360 ; rótulo aprovado Tiotrópio (LUPIN), secção 7.2: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=496b38ee-45b6-4bb2-a35e-9023c3b73719',
   'DailyMed/FDA (NIH/NLM) — approved Ipratropium label (ARMSTRONG), section 7.1: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=133cc2ed-f018-4295-b84e-b24382299360 ; approved Tiotropium label (LUPIN), section 7.2: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=496b38ee-45b6-4bb2-a35e-9023c3b73719', 'published', now()),

  -- Cefalexina × Metformina (rótulo FDA 7.1)
  (LEAST((SELECT id FROM public.drugs WHERE slug = 'cefalexina'),
        (SELECT id FROM public.drugs WHERE slug = 'metformina')),
   GREATEST((SELECT id FROM public.drugs WHERE slug = 'cefalexina'),
            (SELECT id FROM public.drugs WHERE slug = 'metformina')),
   'moderate',
   'Cefalexina + metformina: a cefalexina aumenta as concentrações de metformina — vigiar hipoglicemia.',
   'Cephalexin + metformin: cephalexin increases metformin concentrations — monitor for hypoglycaemia.',
   'O rótulo FDA da cefalexina documenta: "Metformin: increased metformin concentrations. Monitor for hypoglycemia" (7.1). A cefalexina compete com a metformina pela secreção tubular renal (transportador OCT2), reduzindo a sua eliminação e aumentando a exposição sistémica da metformina.',
   'The FDA cephalexin label documents: "Metformin: increased metformin concentrations. Monitor for hypoglycemia" (7.1). Cephalexin competes with metformin for renal tubular secretion (OCT2 transporter), reducing its elimination and increasing metformin systemic exposure.',
   'Vigiar sinais de hipoglicemia em doentes diabéticos durante a antibioterapia com cefalexina.',
   'Monitor for signs of hypoglycaemia in diabetic patients during cephalexin antibiotic therapy.',
   'Monitorizar a glicemia e os sintomas de hipoglicemia durante a associação.',
   'Monitor blood glucose and hypoglycaemia symptoms during the combination.',
   'Hipoglicemia sintomática (sudorese, tremor, confusão) em doente diabético a tomar cefalexina.',
   'Symptomatic hypoglycaemia (sweating, tremor, confusion) in a diabetic patient taking cephalexin.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Cefalexina (PREFERRED PHARMACEUTICALS), secção 7.1: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=553485f8-890d-4929-a6bb-905221cf411d ; rótulo aprovado Metformina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=34496b43-05a2-45fb-a769-52b12e099341',
   'DailyMed/FDA (NIH/NLM) — approved Cephalexin label (PREFERRED PHARMACEUTICALS), section 7.1: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=553485f8-890d-4929-a6bb-905221cf411d ; approved Metformin label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=34496b43-05a2-45fb-a769-52b12e099341', 'published', now()),

  -- Cefalexina × Probenecida (rótulo FDA 7.2)
  (LEAST((SELECT id FROM public.drugs WHERE slug = 'cefalexina'),
        (SELECT id FROM public.drugs WHERE slug = 'probenecida')),
   GREATEST((SELECT id FROM public.drugs WHERE slug = 'cefalexina'),
            (SELECT id FROM public.drugs WHERE slug = 'probenecida')),
   'moderate',
   'Cefalexina + probenecida: a probenecida inibe a secreção tubular da cefalexina — associação não recomendada.',
   'Cephalexin + probenecid: probenecid inhibits cephalexin tubular secretion — combination not recommended.',
   'O rótulo FDA da cefalexina documenta: "Probenecid - The renal excretion of cephalexin is inhibited by probenecid. Co-administration of probenecid with cephalexin is not recommended" (7.2). A probenecida bloqueia a secreção tubular renal dos beta-lactâmicos, elevando e prolongando as concentrações séricas da cefalexina (risco de toxicidade/efeitos adversos dose-dependentes).',
   'The FDA cephalexin label documents: "Probenecid - The renal excretion of cephalexin is inhibited by probenecid. Co-administration of probenecid with cephalexin is not recommended" (7.2). Probenecid blocks the renal tubular secretion of beta-lactams, raising and prolonging serum cephalexin concentrations (risk of dose-dependent toxicity/adverse effects).',
   'Evitar a associação; se a probenecida for essencial, considerar redução da dose ou intervalo da cefalexina.',
   'Avoid the combination; if probenecid is essential, consider reducing the cephalexin dose or extending the interval.',
   'Vigiar sinais de toxicidade (neurotoxicidade, diarreia, reações cutâneas) se a associação for usada.',
   'Monitor for signs of toxicity (neurotoxicity, diarrhoea, skin reactions) if the combination is used.',
   'Neurotoxicidade (confusão, mioclonias) ou efeitos adversos aumentados com a associação.',
   'Neurotoxicity (confusion, myoclonus) or increased adverse effects with the combination.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Cefalexina (PREFERRED PHARMACEUTICALS), secção 7.2: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=553485f8-890d-4929-a6bb-905221cf411d ; rótulo aprovado Probenecida (MARLEX): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5d552de5-2d18-4464-bcaf-0311fa3f080d',
   'DailyMed/FDA (NIH/NLM) — approved Cephalexin label (PREFERRED PHARMACEUTICALS), section 7.2: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=553485f8-890d-4929-a6bb-905221cf411d ; approved Probenecid label (MARLEX): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5d552de5-2d18-4464-bcaf-0311fa3f080d', 'published', now()),

  -- Cefazolina × Probenecida (rótulo FDA 7)
  (LEAST((SELECT id FROM public.drugs WHERE slug = 'cefazolina'),
        (SELECT id FROM public.drugs WHERE slug = 'probenecida')),
   GREATEST((SELECT id FROM public.drugs WHERE slug = 'cefazolina'),
            (SELECT id FROM public.drugs WHERE slug = 'probenecida')),
   'moderate',
   'Cefazolina + probenecida: a probenecida diminui a secreção tubular da cefazolina — associação não recomendada.',
   'Cefazolin + probenecid: probenecid decreases cefazolin tubular secretion — combination not recommended.',
   'O rótulo FDA da cefazolina documenta: "Probenecid may decrease renal tubular secretion of cephalosporins when used concurrently, resulting in increased and more prolonged cephalosporin blood levels. Co-administration of probenecid with Cefazolin is not recommended" (7). O mecanismo é idêntico ao das outras cefalosporinas — bloqueio da secreção tubular renal.',
   'The FDA cefazolin label documents: "Probenecid may decrease renal tubular secretion of cephalosporins when used concurrently, resulting in increased and more prolonged cephalosporin blood levels. Co-administration of probenecid with Cefazolin is not recommended" (7). The mechanism is identical to other cephalosporins — blockade of renal tubular secretion.',
   'Evitar a associação; se a probenecida for essencial, considerar redução da dose da cefazolina.',
   'Avoid the combination; if probenecid is essential, consider reducing the cefazolin dose.',
   'Vigiar sinais de toxicidade se a associação for usada.',
   'Monitor for signs of toxicity if the combination is used.',
   'Efeitos adversos aumentados ou neurotoxicidade com a associação.',
   'Increased adverse effects or neurotoxicity with the combination.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Cefazolina (MEDICAL PURCHASING SOLUTIONS), secção 7: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=79787707-c84f-f229-e053-2a91aa0a1f16 ; rótulo aprovado Probenecida (MARLEX): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5d552de5-2d18-4464-bcaf-0311fa3f080d',
   'DailyMed/FDA (NIH/NLM) — approved Cefazolin label (MEDICAL PURCHASING SOLUTIONS), section 7: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=79787707-c84f-f229-e053-2a91aa0a1f16 ; approved Probenecid label (MARLEX): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5d552de5-2d18-4464-bcaf-0311fa3f080d', 'published', now()),

  -- Cefepima × Gentamicina (rótulo FDA 7.2)
  (LEAST((SELECT id FROM public.drugs WHERE slug = 'cefepima'),
        (SELECT id FROM public.drugs WHERE slug = 'gentamicina')),
   GREATEST((SELECT id FROM public.drugs WHERE slug = 'cefepima'),
            (SELECT id FROM public.drugs WHERE slug = 'gentamicina')),
   'moderate',
   'Cefepima + gentamicina: risco aumentado de nefrotoxicidade e ototoxicidade — monitorizar a função renal.',
   'Cefepime + gentamicin: increased risk of nephrotoxicity and ototoxicity — monitor renal function.',
   'O rótulo FDA da cefepima documenta: "Aminoglycosides: increased potential of nephrotoxicity and ototoxicity. Monitor renal function" (7.2). A associação de uma cefalosporina de 4ª geração com um aminoglicosídeo é comum na terapêutica empírica de infeções graves, mas o risco renal e auditivo aditivo exige monitorização, especialmente no idoso e no doente renal.',
   'The FDA cefepime label documents: "Aminoglycosides: increased potential of nephrotoxicity and ototoxicity. Monitor renal function" (7.2). Combining a fourth-generation cephalosporin with an aminoglycoside is common in empirical therapy of severe infections, but the additive renal and auditory risk requires monitoring, especially in the elderly and renally impaired.',
   'Monitorizar a função renal (creatinina, débito urinário) e vigiar ototoxicidade (tinitus, hipoacusia) durante a associação.',
   'Monitor renal function (creatinine, urine output) and watch for ototoxicity (tinnitus, hearing loss) during the combination.',
   'Vigiar níveis séricos do aminoglicosídeo quando aplicável e sintomas vestibulares/auditivos.',
   'Monitor aminoglycoside serum levels when applicable and vestibular/auditory symptoms.',
   'Aumento da creatinina, oligúria, tinitus ou hipoacusia durante a associação.',
   'Rising creatinine, oliguria, tinnitus or hearing loss during the combination.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Cefepima (WG CRITICAL CARE), secção 7.2: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5fd857e5-591f-44ca-80cf-fd903660b03c ; rótulo aprovado Gentamicina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=441b6232-bb60-40ad-85ec-7c41ba43fd5f',
   'DailyMed/FDA (NIH/NLM) — approved Cefepime label (WG CRITICAL CARE), section 7.2: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5fd857e5-591f-44ca-80cf-fd903660b03c ; approved Gentamicin label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=441b6232-bb60-40ad-85ec-7c41ba43fd5f', 'published', now()),

  -- Cefepima × Amicacina (rótulo FDA 7.2)
  (LEAST((SELECT id FROM public.drugs WHERE slug = 'cefepima'),
        (SELECT id FROM public.drugs WHERE slug = 'amicacina')),
   GREATEST((SELECT id FROM public.drugs WHERE slug = 'cefepima'),
            (SELECT id FROM public.drugs WHERE slug = 'amicacina')),
   'moderate',
   'Cefepima + amicacina: risco aumentado de nefrotoxicidade e ototoxicidade — monitorizar a função renal.',
   'Cefepime + amikacin: increased risk of nephrotoxicity and ototoxicity — monitor renal function.',
   'O rótulo FDA da cefepima documenta a classe: "Aminoglycosides: increased potential of nephrotoxicity and ototoxicity. Monitor renal function" (7.2). A amicacina, aminoglicosídeo de largo espectro, associa-se à cefepima em regimes empíricos de infeções graves — o risco renal e auditivo é aditivo.',
   'The FDA cefepime label documents the class: "Aminoglycosides: increased potential of nephrotoxicity and ototoxicity. Monitor renal function" (7.2). Amikacin, a broad-spectrum aminoglycoside, is combined with cefepime in empirical regimens for severe infections — the renal and auditory risk is additive.',
   'Monitorizar a função renal e vigiar ototoxicidade durante a associação.',
   'Monitor renal function and watch for ototoxicity during the combination.',
   'Vigiar níveis séricos da amicacina quando aplicável.',
   'Monitor amikacin serum levels when applicable.',
   'Aumento da creatinina, oligúria, tinitus ou hipoacusia durante a associação.',
   'Rising creatinine, oliguria, tinnitus or hearing loss during the combination.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Cefepima (WG CRITICAL CARE), secção 7.2: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5fd857e5-591f-44ca-80cf-fd903660b03c ; rótulo aprovado Amicacina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=f260ff2a-76a0-4672-9516-91c344b67890',
   'DailyMed/FDA (NIH/NLM) — approved Cefepime label (WG CRITICAL CARE), section 7.2: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5fd857e5-591f-44ca-80cf-fd903660b03c ; approved Amikacin label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=f260ff2a-76a0-4672-9516-91c344b67890', 'published', now()),

