   GREATEST((SELECT id FROM public.drugs WHERE slug = 'famotidina'),
            (SELECT id FROM public.drugs WHERE slug = 'itraconazol')),
   'moderate',
   'Famotidina + itraconazol: a famotidina reduz a absorção do itraconazol (depende do pH gástrico) — separar as tomas.',
   'Famotidine + itraconazole: famotidine reduces itraconazole absorption (gastric pH-dependent) — separate doses.',
   'O rótulo FDA da famotidina documenta a classe: "Drugs Dependent on Gastric pH for Absorption: Systemic exposure of the concomitant drug may be significantly reduced leading to loss of efficacy" (7.1). O itraconazol (cápsulas) requer pH ácido — a supressão ácida pela famotidina reduz a sua absorção.',
   'The FDA famotidine label documents the class: "Drugs Dependent on Gastric pH for Absorption: Systemic exposure of the concomitant drug may be significantly reduced leading to loss of efficacy" (7.1). Itraconazole (capsules) requires an acidic pH — famotidine acid suppression reduces its absorption.',
   'Separar as tomas por pelo menos 2 horas; considerar solução oral de itraconazol (menos dependente do pH) se necessário.',
   'Separate doses by at least 2 hours; consider itraconazole oral solution (less pH-dependent) if needed.',
   'Avaliar a resposta ao tratamento antifúngico durante a associação.',
   'Assess response to antifungal therapy during the combination.',
   'Falência do tratamento antifúngico com toma simultânea de famotidina.',
   'Failure of antifungal treatment with simultaneous famotidine intake.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Famotidina (TEVA), secção 7.1: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=4c6f4f9e-f3f5-4ecf-9f40-887e037e8847 ; rótulo aprovado Itraconazol: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=a4d555fa-787c-40fb-bb7d-b0d4f7318fd0',
   'DailyMed/FDA (NIH/NLM) — approved Famotidine label (TEVA), section 7.1: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=4c6f4f9e-f3f5-4ecf-9f40-887e037e8847 ; approved Itraconazole label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=a4d555fa-787c-40fb-bb7d-b0d4f7318fd0', 'published', now()),

  -- Famotidina × Atazanavir (rótulo FDA 7.1)
  (LEAST((SELECT id FROM public.drugs WHERE slug = 'famotidina'),
        (SELECT id FROM public.drugs WHERE slug = 'atazanavir')),
   GREATEST((SELECT id FROM public.drugs WHERE slug = 'famotidina'),
            (SELECT id FROM public.drugs WHERE slug = 'atazanavir')),
   'moderate',
   'Famotidina + atazanavir: a famotidina reduz a absorção do atazanavir (depende do pH gástrico) — risco de falência virológica.',
   'Famotidine + atazanavir: famotidine reduces atazanavir absorption (gastric pH-dependent) — risk of virological failure.',
   'O rótulo FDA da famotidina documenta a classe dos fármacos dependentes do pH gástrico (7.1). O atazanavir é um inibidor da protease que requer pH ácido para absorver — a supressão ácida pela famotidina reduz significativamente a sua exposição, com risco de falência virológica no VIH.',
   'The FDA famotidine label documents the class of gastric pH-dependent drugs (7.1). Atazanavir is a protease inhibitor that requires an acidic pH for absorption — famotidine acid suppression markedly reduces its exposure, with a risk of virological failure in HIV.',
   'Separar as tomas por pelo menos 10-12 horas quando possível; consultar as recomendações específicas do atazanavir (espaçamento e dose); considerar alternativa.',
   'Separate doses by at least 10-12 hours when possible; consult atazanavir-specific recommendations (spacing and dose); consider an alternative.',
   'Monitorizar a carga viral do VIH durante a associação prolongada.',
   'Monitor HIV viral load during prolonged combination.',
   'Falência virológica ou aumento da carga viral em doente com VIH a tomar famotidina e atazanavir.',
   'Virological failure or rising viral load in an HIV patient taking famotidine and atazanavir.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Famotidina (TEVA), secção 7.1: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=4c6f4f9e-f3f5-4ecf-9f40-887e037e8847 ; rótulo aprovado Atazanavir: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=165cff62-b284-4a27-a65d-9ec8a5bfcdd8',
   'DailyMed/FDA (NIH/NLM) — approved Famotidine label (TEVA), section 7.1: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=4c6f4f9e-f3f5-4ecf-9f40-887e037e8847 ; approved Atazanavir label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=165cff62-b284-4a27-a65d-9ec8a5bfcdd8', 'published', now()),

  -- Famotidina × Tizanidina (rótulo FDA 7.2)
  (LEAST((SELECT id FROM public.drugs WHERE slug = 'famotidina'),
        (SELECT id FROM public.drugs WHERE slug = 'tizanidina')),
   GREATEST((SELECT id FROM public.drugs WHERE slug = 'famotidina'),
